// Bài 4.2 — Xếp loại
function xepLoai(diem) {
  // Điều kiện "chặn" đứng đầu: ngoài 0–100 thì mọi nhánh sau vô nghĩa
  if (diem < 0 || diem > 100) {
    return "Không hợp lệ";
  } else if (diem >= 80) {      // ngưỡng CAO xét trước,
    return "Giỏi";
  } else if (diem >= 50) {      // rồi mới đến ngưỡng thấp hơn
    return "Đạt";
  } else {
    return "Học lại";
  }
}

