// Bài 4.2 — Tổng số chẵn
function tongChan(n) {
  let tong = 0;                    // cộng dồn: khai báo NGOÀI vòng lặp, một lần
  for (let i = 1; i <= n; i++) {   // <= để tính cả chính n
